package com.example

/**
 * Curated, 100% syllabus-aligned, distinct Flashcards for Geography (භූගෝල විද්‍යාව).
 * Part 2: Categories 11 to 20 (20 distinct questions per category).
 * Strictly guarantees no repeated questions within the same category or across different categories.
 */
object FlashcardBankGeographySetsPart2 {

  fun getCard(setNum: Int, cardNum: Int, grade: String): CardContentTuple? {
    val c = cardNum.coerceIn(1, 20)
    return when (setNum) {
      11 -> if (grade == "10") set11_Grade10[(c - 1) % set11_Grade10.size] else set11_Grade11[(c - 1) % set11_Grade11.size]
      12 -> if (grade == "10") set12_Grade10[(c - 1) % set12_Grade10.size] else set12_Grade11[(c - 1) % set12_Grade11.size]
      13 -> if (grade == "10") set13_Grade10[(c - 1) % set13_Grade10.size] else set13_Grade11[(c - 1) % set13_Grade11.size]
      14 -> if (grade == "10") set14_Grade10[(c - 1) % set14_Grade10.size] else set14_Grade11[(c - 1) % set14_Grade11.size]
      15 -> if (grade == "10") set15_Grade10[(c - 1) % set15_Grade10.size] else set15_Grade11[(c - 1) % set15_Grade11.size]
      16 -> if (grade == "10") set16_Grade10[(c - 1) % set16_Grade10.size] else set16_Grade11[(c - 1) % set16_Grade11.size]
      17 -> if (grade == "10") set17_Grade10[(c - 1) % set17_Grade10.size] else set17_Grade11[(c - 1) % set17_Grade11.size]
      18 -> if (grade == "10") set18_Grade10[(c - 1) % set18_Grade10.size] else set18_Grade11[(c - 1) % set18_Grade11.size]
      19 -> if (grade == "10") set19_Grade10[(c - 1) % set19_Grade10.size] else set19_Grade11[(c - 1) % set19_Grade11.size]
      20 -> if (grade == "10") set20_Grade10[(c - 1) % set20_Grade10.size] else set20_Grade11[(c - 1) % set20_Grade11.size]
      else -> null
    }
  }

  // --- GRADE 10 SET 19: මානව ජනාවාස (ශ්‍රී ලංකාව) ---
  private val set19_Grade10 = listOf(
    CardContentTuple("මානව ජනාවාසයක් (Human Settlement) යනු කුමක්ද?", "මිනිසුන් සිය වාසය, රැකියා සහ සමාජීය ක්‍රියාකාරකම් සඳහා එක්රැස්ව නිවාස ඉදිකරගෙන ජීවත්වන ඕනෑම ප්‍රදේශයකි.", "ග්‍රාමීය සහ නාගරික ලෙස ප්‍රධාන කොටස් 2කි.", "මානව ජනාවාස නිර්වචනය"),
    CardContentTuple("ග්‍රාමීය ජනාවාසයක ප්‍රධාන ලක්ෂණ 3ක් මොනවාද?", "1. ප්‍රාථමික ආර්ථික කටයුතු (කෘෂිකර්මය, ධීවර, සත්ත්ව පාලනය) ප්‍රධාන වීම\n2. අඩු ජන ඝනත්වය සහ ස්වභාවික පරිසරයට සමීප වීම\n3. ශක්තිමත් සාම්ප්‍රදායික සමාජ සබඳතා පැවතීම.", "ස්වයංපෝෂිත ලක්ෂණ වැඩිය.", "ග්‍රාමීය ජනාවාස ලක්ෂණ"),
    CardContentTuple("නාගරික ජනාවාසයක ප්‍රධාන ලක්ෂණ 3ක් මොනවාද?", "1. ද්විතීයික හා තෘතීයික කටයුතු (කර්මාන්ත, සේවා, වෙළඳාම) ප්‍රධාන වීම\n2. අධික ජන ඝනත්වය සහ තට්ටු නිවාස බහුල වීම\n3. දියුණු යටිතල පහසුකම් (මාර්ග, විදුලිය, සන්නිවේදනය) පැවතීම.", "කෘත්‍රිම පරිසරය කැපී පෙනේ.", "නාගරික ජනාවාස ලක්ෂණ"),
    CardContentTuple("ශ්‍රී ලංකාවේ වියළි කලාපයේ දැකිය හැකි සාම්ප්‍රදායික ග්‍රාමීය ජනාවාසය කුමක්ද?", "වැව් ගම්මානය (Tank village).", "වැව කේන්ද්‍ර කරගනිමින් ජනාවාසය, කුඹුර සහ හේන සකස් විය.", "වැව් ගම්මානය"),
    CardContentTuple("සාම්ප්‍රදායික වැව් ගම්මානයක ප්‍රධාන අංග 4 මොනවාද?", "1. වැව (ජල මූලාශ්‍රය) 2. වෙල්යාය (පහළින් පිහිටි කුඹුරු) 3. ගංගොඩ (නිවාස පිහිටි උස්බිම) 4. හේන සහ කැලය (ආරක්ෂිත ඉහළ කලාපය).", "තිරසාර පරිසර පද්ධතියකි.", "වැව, වෙල්යාය, ගංගොඩ, හේන"),
    CardContentTuple("රේඛීය ජනාවාස (Linear Settlements) බහුලව දක්නට ලැබෙන්නේ කිනම් ස්ථානවලද?", "ප්‍රධාන මහාමාර්ග, දුම්රිය මාර්ග, ඇළ මාර්ග හෝ වෙරළ තීරයන් දෙපස රේඛාවක් ලෙස දිවෙන ප්‍රදේශවල.", "ප්‍රවාහන පහසුව ප්‍රධාන හේතුවයි.", "මාර්ග දෙපස රේඛීය ජනාවාස"),
    CardContentTuple("පොකුරු ජනාවාස (Nucleated / Clustered Settlements) ඇතිවීමට හේතු මොනවාද?", "මාර්ග හන්දි, නගර මධ්‍යස්ථාන, වරායවල්, ඛනිජ පතල් හෝ වැව් බැම්ම පහළ වැනි විශේෂ මධ්‍යස්ථාන වටා නිවාස ගොනුවීම.", "එක් තැනක සංකේන්ද්‍රණය වේ.", "හන්දි සහ වැව් ආශ්‍රිත පොකුරු"),
